const express = require('express');
const { checkToken } = require('../auth');

const router = express.Router();
const alertWaiters = new Map();

router.get('/api/users/:userId/live-alerts/poll', checkToken, (req, res) => {
  const { userId } = req.params;

  if (req.user.id !== userId) {
    return res.status(403).json({ error: 'Forbidden: cannot poll notifications for another user' });
  }

  const timer = setTimeout(() => {
    alertWaiters.delete(userId);
    res.json({ alerts: [] });
  }, 15000);

  alertWaiters.set(userId, (alert) => {
    clearTimeout(timer);
    alertWaiters.delete(userId);
    res.json({ alerts: [alert] });
  });
});
